<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox, type FormInstance, type FormRules } from 'element-plus'
import { Plus, Refresh } from '@element-plus/icons-vue'
import { copyRule, emptyGroup, fetchRules, participantOptions, scopeOptions, attributionOptions, settlementOptions, courseOptions, shareWindowOptions, defaultShareWindow, type Rule, type CommissionGroup, type CommissionMode, type CommissionLevel, type CommissionPayout } from './data'

const currentUser = '当前用户'; const loading = ref(false); const loadError = ref(false); const rules = ref<Rule[]>([]); const query = reactive({ keyword: '', status: '' }); const drawerVisible = ref(false); const detailVisible = ref(false); const detailRule = ref<Rule | null>(null); const returnToDetail = ref(false); const editing = ref(false); const saving = ref(false); const formRef = ref<FormInstance>(); const form = reactive<Rule>({ id: 0, name: '', scope: '', selectedCourses: [], attribution: '', settlement: '', enabled: true, createdAt: '', updatedAt: '', createdBy: '', updatedBy: '', groups: [emptyGroup()] })
const helpContext = computed(() => detailVisible.value ? '正在查看规则详情，可点击底部“编辑”进入可编辑表单。' : drawerVisible.value ? (editing.value ? '正在编辑规则，修改后点击“保存”即可更新更新时间。' : '正在新建规则，填写参与人和返还层级后点击“保存”。') : '当前为规则列表，可点击规则名称查看详情或点击“新建分润规则”创建规则。')
const helpMode = computed(() => detailVisible.value ? 'detail' : drawerVisible.value ? (editing.value ? 'edit' : 'create') : 'list')
const shareWindow = ref(defaultShareWindow); const savedShareWindow = ref(defaultShareWindow); const shareUpdatedAt = ref('2026-09-09 10:12:00'); const shareUpdatedBy = ref('张敏')
const shareWindowDirty = computed(() => shareWindow.value !== savedShareWindow.value)
const shareWindowLabel = computed(() => shareWindowOptions.find(item => item.value === shareWindow.value)?.label ?? '')
const shareWindowTip = computed(() => shareWindow.value === 'never' ? '「永久有效」不限制时长，客户打开过分享链接后长期保留分享归因。' : `客户最后一次打开分享链接后，在 ${shareWindowLabel.value} 内下单才计入分享归因；超出后需重新打开链接。`)
const rulesForView = computed(() => rules.value.filter(item => (!query.keyword || item.name.includes(query.keyword)) && (!query.status || (query.status === 'enabled' ? item.enabled : !item.enabled))))
const canAddParticipant = computed(() => participantOptions.some(item => !form.groups.some(group => group.participant === item)))
const formRules: FormRules = { name: [{ required: true, message: '请输入规则名称', trigger: 'blur' }, { max: 50, message: '规则名称不能超过 50 个字', trigger: 'blur' }], scope: [{ required: true, message: '请选择适用范围', trigger: 'change' }], attribution: [{ required: true, message: '请选择客户归因', trigger: 'change' }], settlement: [{ required: true, message: '请选择结算时点', trigger: 'change' }] }
function resetForm(){Object.assign(form,{id:0,name:'',scope:'',selectedCourses:[],attribution:'',settlement:'',enabled:true,createdAt:'',updatedAt:'',createdBy:'',updatedBy:'',groups:[emptyGroup()]})}
function scopeChanged(scope: string){if(scope!=='指定课程')form.selectedCourses=[]}
function saveShareWindow(){savedShareWindow.value=shareWindow.value;shareUpdatedAt.value=dateTimeText();shareUpdatedBy.value=currentUser;ElMessage.success('有效分享时间已保存')}
function openCreate(){editing.value=false;returnToDetail.value=false;resetForm();drawerVisible.value=true}
function openDetail(rule: Rule){detailRule.value=rule;detailVisible.value=true}
function openEdit(rule: Rule, fromDetail = false){editing.value=true;returnToDetail.value=fromDetail;Object.assign(form,copyRule(rule));if(fromDetail)detailVisible.value=false;drawerVisible.value=true}
function addGroup(){if(!canAddParticipant.value){ElMessage.info('参与人已全部配置，不能继续添加');return}form.groups.push(emptyGroup())}
function removeGroup(index:number){if(form.groups.length===1){ElMessage.warning('至少保留一组分润配置');return}form.groups.splice(index,1)}
function addPayout(group: CommissionGroup){const level=(['levelOne','levelTwo','top'] as CommissionLevel[]).find(item=>!group.payouts.some(payout=>payout.level===item));if(level)group.payouts.push({level,mode:'rate',value:null,partnerOnly:false})}
function removePayout(group: CommissionGroup,index:number){if(group.payouts.length===1){ElMessage.warning('至少保留一项返还层级');return}group.payouts.splice(index,1)}
function levelUsed(group: CommissionGroup,level: CommissionLevel,index:number){return group.payouts.some((item,itemIndex)=>itemIndex!==index&&item.level===level)}
function participantUsed(participant:string,index:number){return !!participant && form.groups.some((group,groupIndex)=>groupIndex!==index&&group.participant===participant)}
function levelText(level: CommissionLevel){return level==='levelOne'?'一级':level==='levelTwo'?'二级':'关系顶级'}
function unit(mode:CommissionMode){return mode==='rate'?'%':'元'}
function valueText(value:{mode:CommissionMode;value:number|null}){return value.value===null||value.value===undefined?'未设置':`${value.value}${unit(value.mode)}`}
function payoutText(payout:CommissionPayout){return `${levelText(payout.level)} ${valueText(payout)}${payout.partnerOnly?'（仅合伙人）':''}`}function groupText(group:CommissionGroup){return `${group.participant || '未选择参与人'}：${group.payouts.map(payoutText).join(' · ')}`}
function dateTimeText(date = new Date()){const pad=(value:number)=>String(value).padStart(2,'0'); return `${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`}
async function save(){const valid=await formRef.value?.validate(); if(!valid)return; if(form.scope==='指定课程'&&!form.selectedCourses.length){ElMessage.warning('请选择至少一门指定课程');return} const duplicate=form.groups.find((group,index)=>participantUsed(group.participant,index)); if(duplicate){ElMessage.warning(`参与人“${duplicate.participant}”已配置，请勿重复添加`);return} const complete=form.groups.every(group=>group.participant && group.payouts.length>0 && group.payouts.every(payout=>payout.value!==null&&payout.value>=0&&(payout.mode!=='rate'||payout.value<=100))); if(!complete){ElMessage.warning('请完整填写每项分润值，比例需在 0% 至 100% 之间');return} saving.value=true; await new Promise(resolve=>setTimeout(resolve,350)); const saved=copyRule(form); const timestamp=dateTimeText(); saved.id=editing.value?form.id:Date.now(); saved.createdAt=editing.value?form.createdAt:timestamp; saved.updatedAt=timestamp; saved.createdBy=editing.value?form.createdBy:currentUser; saved.updatedBy=currentUser; if(editing.value){rules.value=rules.value.map(item=>item.id===saved.id?saved:item)}else rules.value=[saved,...rules.value]; saving.value=false;drawerVisible.value=false;if(returnToDetail.value){detailRule.value=saved;detailVisible.value=true;returnToDetail.value=false}ElMessage.success('保存成功')}
async function toggle(rule:Rule,value:boolean){if(!value){try{await ElMessageBox.confirm('禁用后，新订单将不再使用这条分润规则。','确认禁用？',{type:'warning',confirmButtonText:'确认禁用',cancelButtonText:'取消'});rule.enabled=false;ElMessage.success('规则已禁用')}catch{rule.enabled=true}}else{rule.enabled=true;ElMessage.success('规则已启用')}}
async function load(){loading.value=true;loadError.value=false;try{rules.value=await fetchRules()}catch{loadError.value=true}finally{loading.value=false}}
onMounted(load)
</script>
<template><div class="admin-shell"><aside class="sidebar"><div class="brand">优坐标管理系统<span>规则与分润管理</span></div><div class="nav-label">配置中心</div><div class="nav-item active">分润规则</div></aside><main class="workspace"><div class="content-layout"><div class="content-primary"><header class="page-header"><div><h1>分润规则</h1><p>配置订单中参与人的分润方式与分润金额。</p></div><el-button type="primary" :icon="Plus" @click="openCreate">新建分润规则</el-button></header><el-card class="share-window-card" shadow="never"><div class="share-window"><div class="share-window-text"><div class="share-window-title"><h2>有效分享时间</h2><el-tag :type="shareWindowDirty ? 'warning' : 'success'" size="small" effect="plain">{{ shareWindowDirty ? '有未保存修改' : '已生效' }}</el-tag></div><p>{{ shareWindowTip }}</p><span class="share-window-meta">最近更新：{{ shareUpdatedAt }} · {{ shareUpdatedBy }}</span></div><div class="share-window-actions"><el-select v-model="shareWindow" style="width:170px"><el-option v-for="item in shareWindowOptions" :key="item.value" :label="item.label" :value="item.value"/></el-select><el-button type="primary" :disabled="!shareWindowDirty" @click="saveShareWindow">保存</el-button></div></div></el-card><el-card class="rule-card" shadow="never"><div class="section-title"><div><h2>规则列表</h2><span>共 {{ rulesForView.length }} 条</span></div></div><el-form inline class="search-bar"><el-form-item><el-input v-model="query.keyword" clearable placeholder="搜索规则名称" /></el-form-item><el-form-item><el-select v-model="query.status" clearable placeholder="全部状态" style="width:130px"><el-option label="启用" value="enabled"/><el-option label="禁用" value="disabled"/></el-select></el-form-item></el-form><el-alert v-if="loadError" title="规则加载失败，请重试" type="error" show-icon :closable="false"><template #default><el-button link type="danger" :icon="Refresh" @click="load">重新加载</el-button></template></el-alert><el-table v-loading="loading" :data="rulesForView" class="rules-table" row-key="id"><el-table-column label="规则名称" min-width="210"><template #default="{row}"><el-button link type="primary" class="rule-name-link" @click="openDetail(row)">{{ row.name }}</el-button></template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}"><el-switch v-model="row.enabled" inline-prompt active-text="启用" inactive-text="禁用" @change="value=>toggle(row,Boolean(value))"/></template></el-table-column><el-table-column prop="scope" label="适用范围" min-width="130"/><el-table-column label="分润配置" min-width="390"><template #default="{row}"><div class="group-list"><div v-for="group in row.groups" :key="group.participant" class="group-line">{{ groupText(group) }}</div></div></template></el-table-column><el-table-column prop="attribution" label="客户归因" min-width="145"/><el-table-column prop="settlement" label="结算时点" min-width="145"/><el-table-column prop="createdAt" label="创建时间" min-width="170"/><el-table-column prop="updatedAt" label="更新时间" min-width="170"/><el-table-column label="操作" fixed="right" width="90"><template #default="{row}"><el-button link type="primary" @click="openEdit(row)">编辑</el-button></template></el-table-column><template #empty><el-empty description="暂无分润规则"/></template></el-table><div class="table-footer"><span>共 {{ rulesForView.length }} 条</span><el-pagination background layout="prev, pager, next" :total="rulesForView.length" :page-size="10"/></div></el-card></div><aside class="page-help"><div class="help-panel"><h2>页面说明</h2><template v-if="helpMode==='list'"><section class="help-block"><h3>规则列表</h3><dl class="help-list"><dt>搜索与筛选</dt><dd>可按规则名称关键词搜索，也可按启用/禁用状态筛选；清空条件即可恢复全部规则。</dd><dt>分润配置列</dt><dd>每行按“参与人：返还层级 + 数值”分组展示；按比例显示 %，按金额显示 元。</dd><dt>查看详情</dt><dd>点击规则名称打开详情抽屉，可查看完整配置、创建人和最后更新人。</dd><dt>状态开关</dt><dd>列表中可直接启用/禁用规则；禁用前会二次确认，禁用后新订单不再使用该规则。</dd><dt>有效分享时间</dt><dd>全局配置，对所有规则生效：以客户最后一次打开分享链接的时间为计时起点，在设定时长内下单才计入分享归因。可选 1 小时至 15 天，或选择“永久有效”不限制时长；修改后点击“保存”生效。</dd></dl></section><section class="help-block"><h3>列表操作</h3><ul><li>点击“新建分润规则”进入填写页面。</li><li>点击“编辑”直接修改已有规则。</li><li>表格底部显示当前筛选结果数量。</li></ul></section></template><template v-else-if="helpMode==='create'||helpMode==='edit'"><section class="help-block"><h3>{{ helpMode==='create' ? '新建填写规范' : '编辑填写规范' }}</h3><dl class="help-list"><dt>规则名称 · 必填</dt><dd>最多 50 个字，建议按“业务场景 + 分润用途”命名，例如“课程标准分润”。</dd><dt>适用范围 · 必填</dt><dd>只能选择 1 项：全部课程、全部正价课、全部体验课、指定课程、平台综合服务费或合伙人加盟费。</dd><dt>指定课程 · 条件必填</dt><dd>仅选择“指定课程”时出现，支持多选且至少选 1 门；切换到其他范围后已选课程会清空。</dd><dt>客户归因 · 必填</dt><dd>可选邀请注册绑定人、最后销售转化人，用于确定订单归因对象。</dd><dt>结算时点 · 必填</dt><dd>可选交易完成后 7 天、课消后 7 天、人工结算，请按财务实际节点选择。</dd></dl></section><section class="help-block"><h3>分润配置填写规范</h3><dl class="help-list"><dt>参与人 · 至少 1 组</dt><dd>可选注册邀请、销售转化、招聘老师，每个参与人只能配置 1 次；全部添加后按钮自动隐藏。</dd><dt>返还层级 · 每组至少 1 项</dt><dd>可选返给一级、返给二级、返给关系顶级；同组不可重复，最多 3 项。</dd><dt>计算方式与分润值</dt><dd>按比例输入 0～100 的数字（如 10 展示为 10%）；按金额输入大于等于 0 的元金额（如 20 展示为 20 元）。不允许留空或负数。</dd><dt>特殊情况 · 必须为合伙人</dt><dd>勾选后，该返还层级仅当收款对象是合伙人时才产生分润；未勾选则不限身份。同一参与人的不同层级可分别设置。</dd></dl><ul><li>有多组或多项时才显示删除按钮，最后一组/最后一项不可删除。</li><li>点击“保存”后才会提交校验并更新列表。</li></ul></section></template><template v-else><section class="help-block"><h3>详情说明</h3><dl class="help-list"><dt>信息查看</dt><dd>详情中按字段展示规则名称、状态、适用范围、客户归因、结算时点及分润配置。</dd><dt>分润配置</dt><dd>每位参与人独立成组，组内展示返还层级、计算方式和分润值；比例与金额会显示对应单位。</dd><dt>审计信息</dt><dd>创建时间、更新时间精确到秒，并展示创建人和最后更新人。</dd></dl></section><section class="help-block"><h3>详情操作</h3><ul><li>点击底部“编辑”进入可编辑表单，修改后点击“保存”。</li><li>保存成功后回到详情页，更新时间和最后更新人会刷新。</li><li>点击“关闭”返回规则列表。</li></ul></section></template><div class="help-context"><span>当前状态</span><strong>{{ helpContext }}</strong></div></div></aside></div></main><el-drawer v-model="drawerVisible" class="rail-aware-drawer" :modal="false" :title="editing?'编辑分润规则':'新建分润规则'" size="760px" destroy-on-close><el-form ref="formRef" :model="form" :rules="formRules" label-position="top" class="rule-form"><el-form-item label="规则名称" prop="name"><el-input v-model="form.name" maxlength="50" show-word-limit placeholder="请输入规则名称"/></el-form-item><el-form-item label="适用范围" prop="scope"><el-select v-model="form.scope" placeholder="请选择适用范围" @change="scopeChanged"><el-option v-for="item in scopeOptions" :key="item" :label="item" :value="item"/></el-select></el-form-item><el-form-item v-if="form.scope==='指定课程'" label="指定课程" prop="selectedCourses" required><el-select v-model="form.selectedCourses" multiple collapse-tags :max-collapse-tags="3" placeholder="请选择课程"><el-option v-for="course in courseOptions" :key="course" :label="course" :value="course"/></el-select></el-form-item><div class="form-section"><div class="form-section-title"><div><b>分润配置</b></div><el-button v-if="canAddParticipant" link type="primary" :icon="Plus" @click="addGroup">添加参与人</el-button></div><div v-for="(group,index) in form.groups" :key="index" class="edit-group"><div class="group-toolbar"><div class="participant-field"><span>参与人</span><el-select v-model="group.participant" placeholder="请选择参与人"><el-option v-for="item in participantOptions" :key="item" :label="item" :value="item" :disabled="participantUsed(item,index)"/></el-select></div><el-button v-if="form.groups.length>1" link type="danger" @click="removeGroup(index)">删除参与人</el-button></div><div class="payout-header"><span>返还层级</span><span>计算方式</span><span>分润值</span><span>特殊情况</span><span></span></div><div v-for="(payout,payoutIndex) in group.payouts" :key="payoutIndex" class="payout-row"><el-select v-model="payout.level" placeholder="选择层级"><el-option label="返给一级" value="levelOne" :disabled="levelUsed(group,'levelOne',payoutIndex)"/><el-option label="返给二级" value="levelTwo" :disabled="levelUsed(group,'levelTwo',payoutIndex)"/><el-option label="返给关系顶级" value="top" :disabled="levelUsed(group,'top',payoutIndex)"/></el-select><el-select v-model="payout.mode"><el-option label="按比例" value="rate"/><el-option label="按金额" value="amount"/></el-select><el-input v-model.number="payout.value" type="number" min="0" :max="payout.mode==='rate'?100:undefined" :placeholder="payout.mode==='rate'?'输入比例':'输入金额'"><template #suffix>{{ unit(payout.mode) }}</template></el-input><el-checkbox v-model="payout.partnerOnly" class="partner-check">必须为合伙人</el-checkbox><el-button v-if="group.payouts.length>1" link type="danger" @click="removePayout(group,payoutIndex)">删除</el-button></div><el-button class="add-payout" link type="primary" :icon="Plus" :disabled="group.payouts.length>=3" @click="addPayout(group)">添加返还层级</el-button></div></div><el-form-item label="客户归因" prop="attribution"><el-select v-model="form.attribution" placeholder="请选择客户归因"><el-option v-for="item in attributionOptions" :key="item" :label="item" :value="item"/></el-select></el-form-item><el-form-item label="结算时点" prop="settlement"><el-select v-model="form.settlement" placeholder="请选择结算时点"><el-option v-for="item in settlementOptions" :key="item" :label="item" :value="item"/></el-select></el-form-item></el-form><template #footer><div class="drawer-footer"><el-button @click="drawerVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></div></template></el-drawer><el-drawer v-model="detailVisible" class="rail-aware-drawer" :modal="false" :title="detailRule ? `分润规则详情 · ${detailRule.name}` : '分润规则详情'" size="620px" destroy-on-close><template v-if="detailRule"><div class="detail-panel"><div class="detail-grid"><div><span>规则名称</span><strong>{{ detailRule.name }}</strong></div><div><span>状态</span><el-tag :type="detailRule.enabled ? 'success' : 'info'">{{ detailRule.enabled ? '启用' : '禁用' }}</el-tag></div><div><span>适用范围</span><strong>{{ detailRule.scope }}</strong></div><div v-if="detailRule.scope==='指定课程'"><span>指定课程</span><strong>{{ detailRule.selectedCourses.join('、') }}</strong></div><div><span>客户归因</span><strong>{{ detailRule.attribution }}</strong></div><div><span>结算时点</span><strong>{{ detailRule.settlement }}</strong></div><div><span>创建时间</span><strong>{{ detailRule.createdAt }}</strong></div><div><span>更新时间</span><strong>{{ detailRule.updatedAt }}</strong></div><div><span>创建人</span><strong>{{ detailRule.createdBy }}</stron